const A='assets/';
const CATS=['hot','casino','slots','games','fishing'];
const LABEL={hot:'Hot',casino:'Casino',slots:'Slots',games:'Games',fishing:'Fishing',jili:'JILI',pg:'PG',recent:'Recent'};
const GAME={hot:[['Mines',1],['Dice',2],['Chicken',3],['Limbo',4],['Aviator',5],['Lottery Keno',6],['Plinko',7],['Blackjack',8],['Fortune Gems 500',9],['Fortune Garuda 500',10],['Ludo',11],['7UP 7DOWN',12],['Chicken Road 2',13],['Ludo Win',14],['Money Coming',15]],casino:[['Blackjack',8],['Aviator',5],['Chicken Road 2',13],['Fortune Gems 500',9],['Fortune Garuda 500',10],['Ludo',11],['7UP 7DOWN',12]],slots:[['Fortune Gems 500',9],['Fortune Garuda 500',10],['Money Coming',15],['Pappu',16],['Crazy Money',17],['Lucky Spin',14]],games:[['Mines',1],['Dice',2],['Chicken',3],['Limbo',4],['Aviator',5],['Lottery Keno',6]],fishing:[['Jackpot Fishing','fishing/jackpot-fishing'],['Caishen Fishing','fishing/caishen-fishing'],['Dragon Fishing 2','fishing/dragon-fishing-2'],['Mega Fishing','fishing/mega-fishing'],['Ocean King Jackpot','fishing/ocean-king-jackpot'],['Dragon Fishing','fishing/dragon-fishing']]};
const PROVIDERS=[['Dragon Gaming',141,1],['G.GAMES',63,2],['e!a',64,3],['AVATARUX',95,4],['JILI',148,1],['PG SOFT',86,2],['Evolution',74,3],['Ezugi',52,4]];
const PROMOS={Hot:[['Sports Welcome Bonus',1],['Daily Cashback',2],['Gogo Lucky Spin',3]],Deposit:[['First Deposit Offer',5],['Recharge Rewards',4]],Ranking:[['Race Leaderboard',2],['Weekly Ranking',3]],Agent:[['Invite Friends',4]],VIP:[['VIP Privileges',1],['VIP Weekly Rewards',3]]};
const state={page:'home',category:'hot',detail:'hot',provider:'',promo:'Hot',bets:'Casino',transactionFilter:'All',transactionDateFrom:'',transactionDateTo:'',transactionCalendarOpen:false,transactionId:null,mailId:0,mailReturnY:0,keepDrawer:false,more:false,drawer:false,editor:'',editorStep:1,loggedIn:false,loginStep:1,loginReturn:null,download:true,modal:'',sticky:false,homeY:0,content:'',shuffle:0,activity:0,activityOpen:false,banner:0,profile:{avatar:1,nickname:'Winner Paulson',gender:'Male',phone:'',email:'',invite:'',birthday:'',password:''}};
const app=document.getElementById('app');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,size=22)=>{const p={home:'<path d="m3 11 9-8 9 8v10h-7v-7h-4v7H3z"/>',promo:'<path d="M3 6h18v4a2 2 0 0 0 0 4v4H3v-4a2 2 0 0 0 0-4z"/><path d="M12 6v12"/>',cricket:'<path d="m9 3 7-1 3 16-7 2zM7 21l8-2M20 5a2 2 0 1 0 0 4 2 2 0 0 0 0-4"/>',earn:'<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M3 9h18M15 13h3"/>',coin:'<circle cx="12" cy="12" r="9"/><path d="M12 7v10M9 9.5c.6-.8 1.5-1.2 3-1.2 1.8 0 3 .8 3 2 0 1.4-1.3 1.8-3 2.2-1.7.4-3 1-3 2.2 0 1.2 1.2 2 3 2 1.4 0 2.5-.4 3-1.2"/>',ticket:'<rect x="3" y="6" width="18" height="12" rx="2"/><path d="M8 6v12M16 6v12M10 10h4M10 14h3"/>',deposit:'<circle cx="12" cy="12" r="9"/><path d="M12 8v8M8 12h8"/>',withdraw:'<rect x="4" y="5" width="16" height="16" rx="2"/><path d="M12 3v10m-4-4 4 4 4-4"/>',gift:'<rect x="3" y="9" width="18" height="12" rx="1"/><path d="M2 9h20M12 9v12M12 9C5 9 5 2 9 3c2 0 3 3 3 6Zm0 0c7 0 7-7 3-6-2 0-3 3-3 6Z"/>',support:'<path d="M4 13v-2a8 8 0 0 1 16 0v2M4 13H2v5h4v-5zm16 0h2v5h-4v-5zM18 19a8 8 0 0 1-7 3"/>',mail:'<rect x="2" y="5" width="20" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>',menu:'<circle cx="12" cy="4" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="12" cy="20" r="1"/>',back:'<path d="m15 3-9 9 9 9"/>',chevron:'<path d="m8 4 8 8-8 8"/>',close:'<path d="M4 4 20 20M20 4 4 20"/>',gamepad:'<path d="M7 8h10c2 0 3 1 4 5l1 5c1 3-2 4-4 2l-3-3H9l-3 3c-2 2-5 1-4-2l1-5c1-4 2-5 4-5zM7 11v5m-2-2h5m6-1h1m2 2h1"/>',plane:'<path d="m2 13 20-9-6 17-4-6-5 3 2-5z"/>',rocket:'<path d="M12 2c-4 3-6 8-6 13l-3 3 3 3 4-2h4l4 2 3-3-3-3c0-5-2-10-6-13zM12 8a2 2 0 1 0 0 4 2 2 0 0 0 0-4zM9 22l3 2 3-2"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',download:'<path d="M12 2v14m-5-5 5 5 5-5M3 19v3h18v-3"/>',bell:'<path d="M6 17h12l-2-3V9a4 4 0 0 0-8 0v5l-2 3Zm4 3h4"/>',community:'<circle cx="8" cy="8" r="3"/><circle cx="17" cy="8" r="3"/><path d="M2 21v-2a6 6 0 0 1 12 0v2m0 0v-2a5 5 0 0 1 8 0v2"/>',shield:'<path d="m12 2 9 4v6c0 6-4 9-9 11-5-2-9-5-9-11V6zM8 12l3 3 5-6"/>',star:'<path d="m12 2 3 7 7 1-5 5 1 7-6-4-6 4 1-7-5-5 7-1z"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 7 7"/>',eye:'<path d="M2 12s4-6 10-6 10 6 10 6-4 6-10 6S2 12 2 12z"/><circle cx="12" cy="12" r="2"/>',calendar:'<rect x="3" y="5" width="18" height="17" rx="2"/><path d="M3 10h18M8 2v6m8-6v6"/>'};return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${p[name]||p.star}</svg>`};
function status(){return `<div class="statusbar"><span>12:00</span><span class="status-right"><svg class="signal-icon" viewBox="0 0 18 12" width="18" height="12" role="img" aria-label="Mobile signal"><rect x="1" y="8" width="3" height="3" rx=".7"/><rect x="5.5" y="6" width="3" height="5" rx=".7"/><rect x="10" y="3.5" width="3" height="7.5" rx=".7"/><rect x="14.5" y="1" width="3" height="10" rx=".7"/></svg><span class="battery" role="img" aria-label="Battery"></span></span></div>`}
const ACTIVITIES=[{label:'VIP',icon:'star'},{label:'Task',icon:'ticket'},{label:'First Deposit',icon:'deposit'},{label:'Welcome Bonus',icon:'gift'},{label:'Racing',icon:'cricket'}];
function activityFab(){return `<div class="activity-launcher ${state.activityOpen?'is-open':''} ${state.download?'has-download':'no-download'}">${state.activityOpen?`<div class="activity-panel" role="menu" aria-label="Activities"><button class="activity-collapse" data-go="activity-toggle" aria-label="Collapse Activities">${icon('chevron',18)}</button>${ACTIVITIES.map(item=>`<button class="activity-item" data-go="activity:${esc(item.label)}" role="menuitem" aria-label="${esc(item.label)} activity"><span class="activity-item-icon">${icon(item.icon,21)}</span><span>${esc(item.label)}</span></button>`).join('')}</div>`:`<button class="activity-fab" data-go="activity-toggle" aria-expanded="false" aria-label="Open Activities"><span class="activity-fab-arrow">${icon('chevron',20)}</span><span>Activities</span></button>`}</div>`}
function header(){return `<header class="site-header">${status()}<div class="header-main"><button class="wordmark" data-go="home" aria-label="Gogo Home">Gogo<span class="wordmark-spark"></span></button><div class="header-right">${state.loggedIn?`<div class="balance"><span>₹ 999,999.99</span><button data-go="deposit" aria-label="Deposit">+</button></div>`:`<button class="login-cta" data-go="login">Login / Register</button>`}<button class="icon-button" data-go="support" aria-label="Customer support">${icon('support')}</button><button class="icon-button" data-go="messages" aria-label="Messages">${icon('mail')}</button><button class="icon-button" data-go="drawer" aria-label="Personal center">${icon('menu')}</button></div></div></header>`}
function gameSrc(ref){const name=typeof ref==='number'?`game-${String(ref).padStart(2,'0')}`:ref.split('/').pop();return `${A}card-art/${name}.webp`}
function gameCard(g,i){return `<button class="game-card" data-go="game:${esc(g[0])}" aria-label="Open ${esc(g[0])}"><span class="game-art"><img src="${gameSrc(g[1])}" alt="" loading="lazy"><span class="game-title">${esc(g[0])}</span></span><span class="playing"><i></i>${(9999-i*173).toLocaleString()} playing</span></button>`}
function section(cat){const data=GAME[cat],limit=cat==='hot'?9:6,isRail=cat==='games'||cat==='fishing';const gridClass=isRail?'game-grid game-grid-rail':'game-grid';const initial=data.slice(0,limit).map(gameCard).join('');const extra=state.more&&cat==='hot'?`<div class="game-grid more-grid">${data.slice(limit,limit+6).map(gameCard).join('')}</div>`:'';return `<section class="game-section" id="section-${cat}"><div class="section-head"><h2>${LABEL[cat]}</h2><div class="section-head-actions"><button class="text-link" data-go="detail:${cat}">View All ${icon('chevron',13)}</button></div></div><div class="${gridClass}"${isRail?` id="${cat}-rail" aria-label="${LABEL[cat]} games, swipe horizontally"`:''}>${isRail?data.map(gameCard).join(''):initial}</div>${cat==='hot'?(extra+`<button class="more-button" data-go="more" aria-expanded="${state.more}">${state.more?'Show Less':'More'} <span>${state.more?'⌃':'⌄'}</span></button>`):''}</section>`}
function homeTabs(sticky=false){return `<nav class="category-tabs ${sticky?'sticky-tabs':''}" aria-label="Game categories">${CATS.map(c=>`<button data-go="cat:${c}" class="${state.category===c?'active':''}" aria-current="${state.category===c?'true':'false'}">${LABEL[c]}</button>`).join('')}</nav>`}
function liveWins(){const cards=copy=>Array.from({length:12},(_,i)=>{const g=GAME.hot[(i+2)%GAME.hot.length];return `<button class="live-card ${copy==='a'&&i===1?'winner':''}" data-win-id="${i}" data-win-key="${copy}-${i}" data-go="game:${esc(g[0])}" aria-label="${esc(g[0])} win"><img src="${gameSrc(g[1])}" alt=""><b>${esc(g[0])}</b><small>₹ ${(8.6+i*4.3).toFixed(1)}K</small></button>`}).join('');return `<section class="home-block live-block"><div class="section-head"><h2>Live wins</h2><button class="text-link live-bets-link" data-go="bets">All Bets ${icon('chevron',13)}</button></div><div class="horizontal-rail live-rail" aria-label="Live wins, swipe horizontally">${cards('a')}${cards('b')}</div></section>`}
function cricketStrip(){return `<section class="home-block cricket-strip"><div class="section-head"><h2>Cricket</h2><button class="text-link" data-go="cricket">View All ${icon('chevron',13)}</button></div><div class="cricket-cards"><button data-go="cricket" class="cricket-card card-left"><span class="player-art">${icon('cricket',73)}</span><small>SPORTS</small><strong>9WICKET</strong></button><button data-go="cricket" class="cricket-card card-right"><span class="player-art">${icon('cricket',73)}</span><small>CRICKET</small><strong>CRIC BET</strong></button></div></section>`}
function providers(){const cards=PROVIDERS.map(([name,count,n])=>`<button class="provider-card ${n<=4?'provider-art-card':''}" data-go="detail:jili" aria-label="${esc(name)}, ${count} games">${n<=4?`<img src="${A}provider-${n}.webp" alt="" loading="lazy">`:`<strong>${esc(name)}</strong><span>${icon('gamepad',15)} ${count} games</span>`}</button>`).join('');return `<section class="home-block provider-section"><div class="section-head"><h2>Providers</h2><div class="rail-arrows"><button data-go="slide:providers:-1" aria-label="Previous providers">‹</button><button data-go="slide:providers:1" aria-label="Next providers">›</button></div></div><div class="horizontal-rail provider-rail" id="providers-rail">${cards}${cards}</div></section>`}
const BET_NAMES=['Crash','Aviator','Mines','Dice','Plinko','Chicken','Limbo','Fortune Gems'];
function betRow(n){const name=BET_NAMES[n%BET_NAMES.length],player=String((n*37+82)%900+100),amount=(1260+(n*2719)%87640).toLocaleString();return `<div class="bets-row"><span>${icon(name==='Crash'||name==='Aviator'?'plane':'gamepad',14)} ${name}</span><span>P***${player}</span><strong>₹ ${amount} <i class="flag-india" aria-label="India"></i></strong></div>`}
const CRICKET_MATCHES=[['IND','AUS'],['ENG','PAK'],['SA','NZ'],['SL','BAN'],['WI','IND'],['AUS','ENG'],['PAK','SA'],['NZ','SL']];
const CRICKET_PLAYERS=['User932258','come6','User89841','Sonu1028','Player7402','Incognito','A***246','Fan8910'];
function cricketBetRow(n){const [a,b]=CRICKET_MATCHES[n%CRICKET_MATCHES.length],player=CRICKET_PLAYERS[(n*3)%CRICKET_PLAYERS.length],payout=(95+(n*43)%890).toLocaleString();return `<div class="fantasy-row"><span class="cricket-match" aria-label="${a} versus ${b}"><img src="${A}teams/${a.toLowerCase()}.png" alt="${a} team logo"><small>vs</small><img src="${A}teams/${b.toLowerCase()}.png" alt="${b} team logo"><b>${a}–${b}</b></span><span>${player}</span><strong>₹ ${payout} <i class="flag-india" aria-label="India"></i></strong></div>`}
function bets(){return `<section class="home-block bets-section"><div class="section-head"><h2>Bets</h2><span class="live-mark">LIVE <i></i></span></div><div class="segmented"><button class="${state.bets==='Casino'?'active':''}" data-go="bet:Casino">Casino</button><button class="${state.bets==='Cricket'?'active':''}" data-go="bet:Cricket">Cricket</button><button class="${state.bets==='Race'?'active':''}" data-go="bet:Race">Race</button></div>${state.bets==='Cricket'?`<div class="fantasy-bets"><div class="fantasy-head"><span>Game</span><span>Player</span><span>Payout</span></div><div class="fantasy-viewport"><div class="fantasy-data">${Array.from({length:8},(_,i)=>cricketBetRow((state.cricketBetTick||0)+i)).join('')}</div></div></div>`:state.bets==='Race'?`<div class="race-preview"><div class="race-prize"><small>RACE PRIZE POOL</small><strong>₹ 2,00,000</strong><span>Weekly leaderboard · Demo</span></div><div class="race-preview-head"><b>Rank</b><b>Player</b><b>Wager</b><b>Prize</b></div>${[['1','Player ***82','₹ 59,100','₹ 25,000'],['2','Player ***96','₹ 48,300','₹ 15,000'],['3','Player ***43','₹ 35,700','₹ 10,000']].map(r=>`<div class="race-preview-row">${r.map(x=>`<span>${x}</span>`).join('')}</div>`).join('')}<button class="outline-cta" data-go="race">View All ${icon('chevron',14)}</button></div>`:`<div class="bets-table"><div class="bets-row table-head"><span>Game</span><span>Player</span><span>Payout</span></div><div class="bets-viewport"><div class="bets-data">${Array.from({length:8},(_,i)=>betRow((state.betTick||0)+i)).join('')}</div></div></div>`}</section>`}

function footer(){const payments=['VISA','Tether','Paytm','UPI','RuPay'];return `<footer class="site-footer"><div class="trust"><strong>A TRUSTED &amp; SAFE EXPERIENCE</strong><p>Explore games and sports content in one place. Demo values and artwork are illustrative.</p></div><div class="payment-rail horizontal-rail" aria-label="Payment methods, swipe horizontally">${Array.from({length:3},()=>payments.map((name,i)=>`<span class="payment"><img src="${A}payment-${i%4+1}.webp" alt=""><b>${name}</b></span>`).join('')).join('')}</div><button class="responsible" data-go="content:responsible"><span><b>RESPONSIBLE<br>GAMING</b><small>PLAY FOR ENTERTAINMENT. SET LIMITS. TAKE BREAKS.</small></span>${icon('shield',36)}</button><div class="footer-columns"><div><b>HELP</b><button data-go="content:contact">Contact Us</button><button data-go="content:faq">FAQs</button><button data-go="content:download">App Download</button></div><div><b>POLICY</b><button data-go="content:responsible">Responsible Gaming</button><button data-go="content:terms">Terms &amp; Conditions</button><button data-go="content:privacy">Privacy Policy</button></div></div><div class="age-pill"><span>18 YEARS OLD<br>AND ABOVE</span><b>18</b></div><div class="footer-social">${['telegram','discord','x','whatsapp','facebook','instagram'].map(x=>`<button data-go="social:${x}" aria-label="${x}"><img src="${A}social/${x}.png" alt=""></button>`).join('')}</div><p class="version">Version 1.3.0 · Demo2</p></footer>`}
function downloadBar(){return state.download?`<div class="download-bar"><button class="download-close" data-go="download-close" aria-label="Close download bar">${icon('close',16)}</button><div class="download-copy"><b>Gogo App</b><small>Download for a smoother experience</small></div><div class="download-actions"><button class="screen-cta" data-go="modal:Add to screen">Add to screen</button><button class="download-cta" data-go="content:download">Download</button></div></div>`:''}
function nav(){const active=state.page==='promo'?'promo':state.page==='cricket'?'cricket':'home',showRocket=state.page==='home'&&state.sticky;return `<nav class="bottom-nav" aria-label="Main navigation">${[['home','Gogo',showRocket?'rocket':'home'],['promo','Promo','promo'],['cricket','Cricket','cricket'],['earn','Earn','earn'],['get500','Get 500','gift']].map(([id,label,shape])=>`<button data-go="nav:${id}" class="${id===active?'active':''} ${id==='cricket'?'cricket-nav':''}" aria-label="${id==='home'&&showRocket?'Back to top':label}"><span class="nav-icon">${icon(shape,id==='cricket'?29:24)}</span><span>${id==='home'&&showRocket?'Top':label}</span></button>`).join('')}</nav>`}
const BANNERS=[{theme:'cricket',label:'CRICKET',title:'LIVE MATCHES',accent:'FOLLOW THE ACTION',copy:'Top fixtures &amp; live markets',action:'Explore Cricket',go:'cricket'},{theme:'games',label:'GAMES',title:'PLAY YOUR WAY',accent:'FIND YOUR FAVORITE',copy:'Discover games across the lobby',action:'Explore Games',go:'detail:games',art:'banner-games.svg'},{theme:'sports',label:'SPORTS',title:'MATCH DAY',accent:'GET IN THE GAME',copy:'Follow cricket and live fixtures',action:'Explore Cricket',go:'cricket',art:'banner-sports.svg'}];
function banner(){return `<section class="banner-carousel" aria-label="Featured banners" aria-roledescription="carousel"><div class="banner-track">${BANNERS.map((item,i)=>`<div class="hero hero-${item.theme}" role="group" aria-roledescription="slide" aria-label="${i+1} of ${BANNERS.length}: ${item.title}" aria-hidden="${i!==state.banner}">${item.art?`<img class="hero-art" src="${A}${item.art}" alt="">`:'<div class="hero-ball"></div>'}<div class="hero-copy"><small>${item.label}</small><h1>${item.title}</h1><b>${item.accent}</b><p>${item.copy}</p><button data-go="${item.go}" tabindex="${i===state.banner?0:-1}">${item.action} ${icon('chevron',15)}</button></div></div>`).join('')}</div><div class="banner-dots" aria-label="Choose banner">${BANNERS.map((item,i)=>`<button type="button" data-go="banner:${i}" class="${i===state.banner?'active':''}" aria-label="Show banner ${i+1}: ${item.title}" aria-current="${i===state.banner?'true':'false'}"></button>`).join('')}</div></section>`}
function home(){return `${header()}<main class="home-main">${banner()}${liveWins()}${cricketStrip()}<div class="sticky-stack" id="sticky-stack">${homeTabs(true)}</div>${homeTabs()}<div class="category-content">${CATS.filter(c=>!state.hideBefore||CATS.indexOf(c)>=CATS.indexOf(state.category)).map(section).join('')}</div>${providers()}${bets()}${footer()}</main>${downloadBar()}${nav()}${activityFab()}`}
function detail(){const cat=state.detail,all=cat==='jili'?GAME.hot.concat(GAME.slots):GAME[cat]||GAME.hot;const start=state.shuffle%all.length;const games=all.slice(start).concat(all.slice(0,start));return `${header()}<main class="subpage"><div class="page-title"><button class="back-button" data-go="home-back" aria-label="Back to Home">${icon('back')}</button><h1>${LABEL[cat]||'Games'}</h1></div><div class="detail-filter horizontal-rail">${['recent','hot','casino','slots','jili','pg','games','fishing'].map(c=>`<button data-go="detail:${c}" class="${cat===c?'active':''}"><span class="filter-icon">${icon(c==='casino'?'star':c==='fishing'?'plane':'gamepad',20)}</span><span>${LABEL[c]}</span></button>`).join('')}</div><div class="detail-summary"><span>${games.length} games</span><button data-go="shuffle">${icon('search',16)} Explore</button></div><div class="game-grid detail-grid">${games.concat(games.slice(0,6)).map(gameCard).join('')}</div>${footer()}</main>`}
function promo(){return `${header()}<main class="subpage promo-page"><nav class="promo-tabs horizontal-rail">${Object.keys(PROMOS).map(c=>`<button data-go="promo:${c}" class="${state.promo===c?'active':''}">${c}</button>`).join('')}</nav><div class="promo-list">${PROMOS[state.promo].map(([title,n])=>`<button class="promo-banner" data-go="offer:${title}"><img src="${A}promo-banner-${n}.webp" alt="Promotion artwork"><span class="promo-overlay"><b>${title}</b><small>View activity details ${icon('chevron',13)}</small></span></button>`).join('')}</div>${footer()}</main>${nav()}`}
function race(){let rows=[['1','Player ***82','₹ 59,100','₹ 25,000'],['2','Player ***96','₹ 48,300','₹ 15,000'],['3','Player ***43','₹ 35,700','₹ 10,000'],['4','Player ***73','₹ 30,300','₹ 8,000'],['5','Player ***16','₹ 25,200','₹ 6,000'],['6','Player ***29','₹ 18,800','₹ 4,000'],['7','Player ***67','₹ 15,900','₹ 3,000']];return `${header()}<main class="subpage race-page"><div class="page-title"><button class="back-button" data-go="home-back" aria-label="Back to Home">${icon('back')}</button><h1>Prize Pool</h1></div><div class="race-pool"><small>GOGO RACE</small><strong>₹ 2,00,000</strong><span>Weekly leaderboard · illustrative rewards</span></div><div class="race-ranking"><h2>Leaderboard</h2><div class="race-preview-head"><b>Rank</b><b>Player</b><b>Wager</b><b>Prize</b></div>${rows.map(r=>`<div class="race-preview-row">${r.map(x=>`<span>${x}</span>`).join('')}</div>`).join('')}</div></main><div class="race-login"><b>Log in to view your race position</b><button data-go="login">Log In</button></div>${nav()}`}
function cricket(){return `${header()}<main class="subpage cricket-page"><div class="page-title"><button class="back-button" data-go="home-back" aria-label="Back to Home">${icon('back')}</button><h1>Cricket</h1></div><div class="cricket-hero"><small>FANTASY CRICKET</small><h2>Make your picks.<br>Follow the match.</h2><p>Explore upcoming fixtures and leaderboard previews.</p></div><div class="cricket-subtabs"><button class="active">Recommended</button><button data-go="modal:Starting Soon">Starting Soon</button><button data-go="modal:Popular">Popular</button></div>${[['India','West Indies','Today · 9:30 PM'],['Melbourne Renegades','Melbourne Stars','Tomorrow · 11:30 AM'],['Australia Women','Bangladesh Women','Tomorrow · 2:00 PM']].map(([a,b,t])=>`<button class="match-card" data-go="match:${a} vs ${b}"><span>${icon('cricket',18)} CRICKET · T20</span><strong>${a} <em>VS</em> ${b}</strong><small>${t}</small><b>View match ${icon('chevron',14)}</b></button>`).join('')}</main>${nav()}`}
function drawer(){const actions=[['Notifications','bell','notifications'],['Transactions','earn','transactions'],['Gifts','gift','gifts'],['Community','community','modal:Community'],['Download App','download','content:download']];const unread=typeof MAILS!=='undefined'&&MAILS.some(mail=>!mail.read);return `<div class="scrim" data-go="drawer-close"></div><aside class="drawer" role="dialog" aria-modal="true" aria-label="Personal center"><button class="drawer-x" data-go="drawer-close" aria-label="Close">${icon('close',21)}</button><button class="drawer-profile" data-go="profile" aria-label="Edit your profile"><span class="drawer-avatar"><img src="${A}profile/avatar-${state.profile.avatar}.png" alt="Current avatar"><span class="avatar-edit-mark" aria-hidden="true">${pencilIcon()}</span></span><span><b>${esc(state.profile.nickname)}</b><small>Personal Center</small></span>${icon('chevron',18)}</button><div class="drawer-balance"><small>Balance</small><b>₹ 999,999.99</b><div><button data-go="deposit">${icon('deposit',16)}<span>Deposit</span></button><button data-go="withdraw">${icon('withdraw',16)}<span>Withdraw</span></button></div></div><div class="vip-grid"><button class="vip-card" data-go="modal:VIP details" aria-label="VIP 20 details"><span class="vip-card-top"><b>VIP 20</b><span class="vip-medal" aria-hidden="true">20</span></span><span class="vip-levels"><span>VIP 20</span><span>VIP 20</span></span><span class="vip-deposit"><span>VIP progress</span><span></span></span><span class="vip-detail">Detail</span><i aria-hidden="true"></i></button><button class="club-card" data-go="modal:Club Level" aria-label="Club Level 3 details"><span class="club-title"><b>Club Level</b><em>LV 3</em></span><span class="club-rule"></span><span class="club-withdraw">Withdrawable</span><strong>₹ 999.99</strong></button></div><div class="drawer-links">${actions.map(([label,ico,go])=>`<button data-go="${go}">${icon(ico,19)} <span>${label}</span>${label==='Notifications'&&unread?'<i class="notification-dot" aria-label="Unread notifications"></i>':''}${icon('chevron',16)}</button>`).join('')}</div><div class="drawer-bottom"><button class="support-round" data-go="support">${icon('support',27)}<strong>24</strong><small>24/7 Support</small></button><div class="drawer-social">${['telegram','discord','x','whatsapp','facebook','instagram'].map(x=>`<button data-go="social:${x}" aria-label="${x}"><img src="${A}social/${x}.png" alt=""></button>`).join('')}</div><button class="logout" data-go="logout">Log Out</button><small class="drawer-version">Version 1.3.0</small></div></aside>`}function profile(){
  const p=state.profile;
  const rows=[
    ['Avatar',`<img src="${A}profile/avatar-${p.avatar}.png" alt="Current avatar" class="profile-mini-avatar">`,'avatar'],
    ['Support ID','232323723729834747','support'],
    ['Nickname',esc(p.nickname),'nickname'],
    ['Gender',esc(p.gender),'gender'],
    ['My Invitation Code','98HFGY','invite']
  ];
  const settings=[
    ['Bind Phone No.',p.phone||'Not bound','phone',!p.phone],
    ['E-Mail',p.email||'Not bound','email',!p.email],
    ['Login Password',p.password?'••••••••':'Not set','password',!p.password],
    ['Bind Invitation Code',p.invite||'Not bound','bind',!p.invite],
    ['Bind Birthday',p.birthday||'Not bound','birthday',!p.birthday]
  ];
  return `${header()}<main class="subpage profile-page"><div class="page-title"><button class="back-button" data-go="home-back" aria-label="Back to Home">${icon('back')}</button><h1>My Info</h1></div><h2>Profile</h2>${rows.map(profileRow).join('')}<h2>Setting</h2>${settings.map(profileRow).join('')}</main>`;
}
function pencilIcon(){return '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m15 4 5 5M4 15 16 3a2 2 0 0 1 3 0l2 2a2 2 0 0 1 0 3L9 20l-6 1z"/></svg>'}
function copyIcon(){return '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="8" y="7" width="12" height="14" rx="2"/><path d="M16 7V5a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v11a2 2 0 0 0 2 2h2"/></svg>'}
function profileRow([label,value,key,pending=false]){
  const copy=key==='support'||key==='invite';
  const assets={avatar:'icon-avatar.png',support:'icon-support.png',nickname:'icon-nickname.png',gender:'icon-gender.png',invite:'icon-invite.png',phone:'icon-phone.png',email:'icon-email.png',password:'icon-password.png',bind:'icon-bind.png',birthday:'icon-birthday.png'};
  const image=`<img src="${A}profile/${assets[key]}" alt="" class="profile-row-icon-image">`;
  return `<button class="profile-row" data-go="${copy?'copy:':'edit:'}${key}" aria-label="${copy?'Copy ':''}${label}"><span class="profile-row-icon">${image}</span><b>${label}</b><span class="profile-value">${value}</span>${pending?'<i class="profile-setting-dot" aria-label="Setup required"></i>':''}${copy?`<span class="profile-copy-icon" aria-hidden="true">${copyIcon()}</span>`:icon('chevron',16)}</button>`;
}
function editorHint(image,text){return `<div class="edit-hint"><img src="${A}profile/${image}" alt=""><span>${text}</span></div>`}
const verificationDeadlines={login:0,phone:0,email:0,password:0};
function startVerificationCountdown(kind){verificationDeadlines[kind]=Date.now()+60000;syncVerificationCountdowns()}
function verificationField(id,placeholder,kind){const seconds=Math.max(0,Math.ceil((verificationDeadlines[kind]-Date.now())/1000));return `<div class="verification-field" data-verification="${kind}"><input id="${id}" inputmode="numeric" autocomplete="one-time-code" maxlength="6" placeholder="${placeholder}"><span class="verification-countdown" ${seconds?'':'hidden'}>${seconds}s</span><button type="button" class="verification-resend" data-go="verify-resend:${kind}" ${seconds?'hidden':''}>Resend</button></div>`}
function syncVerificationCountdowns(){document.querySelectorAll('[data-verification]').forEach(field=>{const seconds=Math.max(0,Math.ceil((verificationDeadlines[field.dataset.verification]-Date.now())/1000));const counter=field.querySelector('.verification-countdown'),resend=field.querySelector('.verification-resend');counter.textContent=`${seconds}s`;counter.hidden=seconds===0;resend.hidden=seconds>0})}
function editor(){
  const type=state.editor,p=state.profile,step=state.editorStep;
  const title={avatar:'Avatar',nickname:'Nickname',gender:'Gender',phone:'Bind Phone No.',email:'E-mail',password:'Set Password',bind:'Bind Invitation Code',birthday:'Bind Birthday'}[type]||type;
  let body='',bubble='';
  if(type==='avatar')body=`<p>Choose your avatar</p><div class="avatar-grid">${[1,2,3,4,5,6].map(n=>`<button data-go="avatar:${n}" class="${p.avatar===n?'selected':''}" aria-label="Avatar ${n}"><img src="${A}profile/avatar-${n}.png" alt=""></button>`).join('')}</div>`;
  else if(type==='nickname')body=`<label for="edit-value">Please enter your nickname</label><div class="nickname-field"><input id="edit-value" maxlength="30" autocomplete="nickname" value="${esc(p.nickname)}" placeholder="Enter nickname"><button type="button" data-go="nickname-clear" aria-label="Clear nickname">${icon('close',18)}</button></div>`;
  else if(type==='gender')body=`<p>Choose your gender</p><div class="choice-row"><button data-go="gender:Male" class="${(state.editGender||p.gender)==='Male'?'selected':''}"><img src="${A}profile/icon-male.png" alt="">Male</button><button data-go="gender:Female" class="${(state.editGender||p.gender)==='Female'?'selected':''}"><img src="${A}profile/icon-female.png" alt="">Female</button></div>`;
  else if(type==='phone'){
    if(step===1){body=`<label>Please enter your Phone No.<input id="edit-value" type="tel" inputmode="tel" autocomplete="tel" placeholder="Phone Number"></label>${editorHint('icon-gift.png','Complete registration to explore rewards <b>· Demo</b>')}`;bubble='₹200 · Demo'}
    else {body=`<label for="edit-value">Verification code</label>${verificationField('edit-value','6-digit code','phone')}<p class="edit-note">Enter the demo code for ${esc(state.editDraft||'your number')}.</p>${editorHint('icon-gift.png','Complete registration to explore rewards <b>· Demo</b>')}`;bubble='₹200 · Demo'}
  }
  else if(type==='email'){
    if(step===1){body=`<label>Link your e-mail<input id="edit-value" type="email" inputmode="email" autocomplete="email" placeholder="E-mail"></label>${editorHint('icon-gift.png','Enjoy exclusive prizes &amp; news')}${editorHint('icon-secure.png','Use e-mail to sign in or reset your password')}`;bubble='₹100 · Demo'}
    else {body=`<label for="edit-value">Verification code</label>${verificationField('edit-value','6-digit code','email')}<p class="edit-note">Enter the demo code for ${esc(state.editDraft||'your e-mail')}.</p>${editorHint('icon-gift.png','Enjoy exclusive prizes &amp; news')}${editorHint('icon-secure.png','Use e-mail to sign in or reset your password')}`;bubble='₹100 · Demo'}
  }
  else if(type==='bind')body=`<label>Please enter your Invitation Code<input id="edit-value" maxlength="16" value="${esc(p.invite)}" placeholder="Invitation Code"></label><p class="edit-note">Only allowed to enter once!</p>`;
  else if(type==='birthday'){
    const [savedDay='',savedMonth='']=p.birthday.split('/');
    body=`<label>Provide your birthday to enjoy exclusive benefits</label><div class="birthday-selects"><div class="day-picker"><input id="edit-day" type="hidden" value="${savedDay}"><button type="button" class="day-trigger" data-go="day-toggle" aria-label="Day" aria-haspopup="listbox" aria-expanded="false">${savedDay?Number(savedDay):'Day'}<span aria-hidden="true">⌄</span></button><div class="day-options" role="listbox" aria-label="Day" hidden>${Array.from({length:31},(_,i)=>{const v=String(i+1).padStart(2,'0');return `<button type="button" role="option" aria-selected="${savedDay===v}" data-go="day-select:${v}">${i+1}</button>`}).join('')}</div></div><select id="edit-month" aria-label="Month"><option value="">Month</option>${Array.from({length:12},(_,i)=>{const v=String(i+1).padStart(2,'0');return `<option value="${v}" ${savedMonth===v?'selected':''}>${i+1}</option>`}).join('')}</select></div>${editorHint('icon-crown.png','Birthday information is used only for birthday celebrations')}${editorHint('icon-gem.png','Check birthday benefits on the VIP page.')}`;
    bubble='VIP perks';
  }
  else if(type==='password'){
    if(step===1)body=`<label for="edit-value">Please enter your verification code</label>${verificationField('edit-value','Verification Code','password')}<p class="edit-note">Demo verification code for +91 xxx…</p>`;
    else body=`<label>New password<input id="edit-password" type="password" autocomplete="new-password" placeholder="Enter password"></label><label class="edit-second-label">Confirm password<input id="edit-confirm" type="password" autocomplete="new-password" placeholder="Re-enter password"></label><p class="edit-note">Use at least 6 characters for this demo password.</p>`;
  }
  const next=['phone','email','password'].includes(type)&&step===1;
  const buttonLabel=next?'Next':type==='phone'&&step===2?'Verify':['email','password','bind','birthday'].includes(type)?'Confirm':'Save';
  return `<div class="sheet-scrim" data-go="edit-close"></div><section class="edit-sheet edit-sheet--${type}" role="dialog" aria-modal="true" aria-label="${title}"><div class="sheet-handle"></div><button class="sheet-x" data-go="edit-close" aria-label="Close editor">${icon('close')}</button><h2>${title}</h2>${next?'<div class="step-mark">Step 1 of 2</div>':step===2?'<div class="step-mark">Step 2 of 2</div>':''}<div class="edit-body">${body}</div>${bubble?`<span class="edit-reward-bubble" aria-hidden="true">${bubble}</span>`:''}<button class="sheet-submit" data-go="edit-${next?'next':'save'}">${buttonLabel}</button></section>`;
}
let toastTimer;
function showToast(message){
  let toast=document.querySelector('.feedback-toast');
  if(!toast){toast=document.createElement('div');toast.className='feedback-toast';toast.setAttribute('role','status');document.body.appendChild(toast)}
  toast.textContent=message;
  toast.classList.add('shown');
  clearTimeout(toastTimer);
  toastTimer=setTimeout(()=>{toast.classList.remove('shown');setTimeout(()=>toast.remove(),220)},2200);
}
async function copyProfileValue(key){
  const value=key==='support'?'232323723729834747':key==='invite'?'98HFGY':'';
  if(!value)return;
  try{
    if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(value);
    else{
      const input=document.createElement('textarea');input.value=value;input.style.position='fixed';input.style.opacity='0';document.body.appendChild(input);input.select();const copied=document.execCommand('copy');input.remove();if(!copied)throw Error('Copy unavailable');
    }
    showToast('Copied successfully');
  }catch{showToast('Copy unavailable')}
}
function login(){const second=state.loginStep===2;return `<div class="login-screen"><header class="login-topbar"><span class="wordmark" aria-label="Gogo">Gogo<span class="wordmark-spark"></span></span><button class="login-close" data-go="login-close" aria-label="Close login">${icon('close',22)}</button></header><main class="login-page"><div class="login-panel"><div class="login-intro"><span class="login-kicker">WELCOME TO GOGO</span><h1>${second?'Verification code':'Welcome to Gogo'}</h1><p>${second?'Enter the demo code to continue.':'Enter your mobile number to continue.'}</p></div><div class="login-fields">${second?`<label for="login-input">Verification code</label>${verificationField('login-input','4–6 digit code','login')}`:`<label for="login-input">Mobile number</label><input id="login-input" type="tel" inputmode="tel" autocomplete="tel" placeholder="Enter mobile number">`}</div><button class="primary-button" data-go="login-${second?'submit':'next'}">${second?'Login':'Continue'}</button></div></main></div>`}
const CONTENT={contact:'Contact Us',faq:'FAQs',download:'App Download',privacy:'Privacy Policy',terms:'Terms & Conditions',responsible:'Responsible Gaming'};
function content(){const k=state.content;let body=k==='contact'?`<p>For assistance with your account or the demo, please contact support.</p><div class="contact-emails"><div><a href="mailto:support@comevip.com">support@comevip.com</a><p>For questions and technical issues</p></div><div><a href="mailto:business@comevip.com">business@comevip.com</a><p>For marketing and partnership proposals</p></div></div>`:k==='faq'?`${['How do I sign in?','Where can I see promotions?','How do I update my profile?'].map(x=>`<details><summary>${x}</summary><p>This prototype demonstrates the intended interaction. No real-money account or transaction is connected.</p></details>`).join('')}`:k==='download'?`<p>Install the app for quicker access on your mobile device.</p><button class="primary-button" data-go="modal:App Download">Download</button>`:k==='responsible'?`<p>Set a time and spending limit before you play. Take breaks and never chase losses.</p><p>This page is demo content and requires approved production copy before launch.</p>`:`<p>This is demonstration copy for the interactive prototype. Approved ${CONTENT[k]} text must be supplied before a production release.</p>`;return `${header()}<main class="subpage content-page"><div class="page-title"><button class="back-button" data-go="content-back" aria-label="Back to Home">${icon('back')}</button><h1>${CONTENT[k]}</h1></div><div class="content-body">${body}</div>${footer()}</main>`}
function gifts(){return `${header()}<main class="gifts-page"><div class="page-title"><button class="back-button" data-go="home-back" aria-label="Back to Home">${icon('back')}</button><h1>Gifts</h1></div><section class="gifts-intro"><span class="gifts-symbol" aria-hidden="true">${icon('gift',30)}</span><h2>Redeem a gift code</h2><p>Enter your gift code below to check your reward.</p></section><form class="gift-form" id="gift-form"><label for="gift-code">Gift code</label><input id="gift-code" name="gift-code" type="text" autocomplete="off" maxlength="32" placeholder="Please enter the gift code" aria-describedby="gift-help"><p id="gift-help">Codes are case insensitive. Each code can be used once.</p><button class="gift-confirm" type="submit">Confirm</button></form><p class="gifts-footnote">This demo shows the redemption flow. No reward is issued.</p></main>`}
function modal(){const screenHelp=state.modal==='Add to screen';return `<div class="modal-scrim" data-go="modal-close"><div class="modal" role="dialog" aria-modal="true" aria-label="${esc(state.modal)}"><h2>${esc(state.modal)}</h2>${screenHelp?`<p>Keep Gogo one tap away by adding a shortcut to your home screen.</p><p><b>iPhone / iPad:</b> Open this page in Safari, tap Share, then choose Add to Home Screen.</p><p><b>Android:</b> Open your browser menu and choose Add to Home screen or Install app, if available.</p><p><b>Desktop:</b> Open your browser menu and look for Create shortcut or Install this site as an app.</p>`:`<p>This interactive demo shows the intended entry. No transaction or game session is started.</p>`}<button data-go="modal-close">Close</button></div></div>`}
let bannerManualUntil=0;
function selectBanner(index,manual=false){const carousel=document.querySelector('.banner-carousel');if(!carousel||state.page!=='home')return;state.banner=(index+BANNERS.length)%BANNERS.length;if(manual)bannerManualUntil=Date.now()+7000;carousel.querySelector('.banner-track').style.transform=`translateX(-${state.banner*100}%)`;carousel.querySelectorAll('.hero').forEach((slide,i)=>{slide.setAttribute('aria-hidden',i===state.banner?'false':'true');slide.querySelector('button').tabIndex=i===state.banner?0:-1});carousel.querySelectorAll('.banner-dots button').forEach((dot,i)=>{dot.classList.toggle('active',i===state.banner);dot.setAttribute('aria-current',i===state.banner?'true':'false')})}
function render(){app.innerHTML=(state.page==='home'?home():state.page==='detail'?detail():state.page==='promo'?promo():state.page==='race'?race():state.page==='cricket'?cricket():state.page==='profile'?profile():state.page==='login'?login():state.page==='gifts'?gifts():state.page==='notifications'?notifications():state.page==='mail-detail'?mailDetails():state.page==='transactions'?transactions():content())+(state.drawer?drawer():'')+(state.editor?editor():'')+(state.modal?modal():'')+(state.transactionId?transactionDetail():'');document.body.classList.toggle('overlay-open',!!(state.drawer||state.editor||state.modal||state.transactionId));document.body.classList.toggle('login-mode',state.page==='login');document.body.classList.toggle('content-mode',state.page==='content'||state.page==='detail'||state.page==='gifts'||state.page==='notifications'||state.page==='mail-detail'||state.page==='transactions');document.body.classList.toggle('gifts-mode',state.page==='gifts');document.body.classList.toggle('profile-mode',state.page==='profile');selectBanner(state.banner);syncVerificationCountdowns();syncSticky();syncActivityPosition()}
function syncActivityPosition(){const launcher=document.querySelector('.activity-launcher');if(!launcher)return;const nav=document.querySelector('.bottom-nav');const download=document.querySelector('.download-bar');const anchor=launcher.classList.contains('is-open')?nav:(download||nav);const appShell=document.querySelector('#app');if(!anchor||!appShell)return;const edge=anchor.getBoundingClientRect();const shell=appShell.getBoundingClientRect();const inset=0;const layoutWidth=document.body?.clientWidth||document.documentElement.clientWidth||window.innerWidth;launcher.style.right=`${Math.max(0,layoutWidth-shell.right+inset)}px`;launcher.style.bottom=`${Math.max(0,window.innerHeight-edge.top+inset)}px`}
function setPage(page){if(state.page==='home')state.homeY=window.scrollY;state.page=page;state.sticky=false;state.drawer=false;state.editor='';state.modal='';window.scrollTo({top:0,behavior:'instant'});render();history.pushState({page},'',`#${page}`)}
function homeReset(){state.page='home';state.category='hot';state.hideBefore=false;state.more=false;state.banner=0;state.keepDrawer=false;state.drawer=false;state.editor='';state.modal='';window.scrollTo({top:0,behavior:'instant'});render();history.pushState({page:'home'},'','#home')}
function homeBack(){state.page='home';state.drawer=state.keepDrawer;state.keepDrawer=false;state.editor='';state.modal='';window.scrollTo({top:0,behavior:'instant'});render();window.scrollTo({top:state.homeY,behavior:'instant'});syncSticky();history.pushState({page:'home'},'','#home')}
function closeLogin(){const previous=state.loginReturn||{page:'home',scrollY:state.homeY};state.loginReturn=null;state.loginStep=1;state.page=previous.page;state.sticky=false;state.drawer=false;state.editor='';state.modal='';window.scrollTo({top:0,behavior:'instant'});render();window.scrollTo({top:previous.scrollY,behavior:'instant'});if(state.page==='home')syncSticky();history.replaceState({page:state.page},'',`#${state.page}`)}
function openCategory(cat){window.scrollTo({top:0,behavior:'instant'});state.page='home';state.category=cat;state.hideBefore=cat!=='hot';state.more=false;state.drawer=false;render();const el=document.getElementById(`section-${cat}`);const y=el?window.scrollY+el.getBoundingClientRect().top-156:0;window.scrollTo({top:Math.max(0,y),behavior:'instant'});state.category=cat;syncSticky()}
function syncCategoryFromScroll(){if(state.page!=='home')return;const sections=[...document.querySelectorAll('.category-content .game-section')];if(!sections.length)return;const marker=169;let active=sections[0].id.replace('section-','');for(const section of sections){if(section.getBoundingClientRect().top<=marker)active=section.id.replace('section-','')}if(active!==state.category){state.category=active}document.querySelectorAll('.category-tabs button[data-go^="cat:"]').forEach(button=>{const cat=button.dataset.go.slice(4);const selected=cat===active;button.classList.toggle('active',selected);button.setAttribute('aria-current',selected?'true':'false')})}
function syncSticky(){const stack=document.getElementById('sticky-stack');if(!stack)return;const tabs=document.querySelector('.home-main > .category-tabs');const should=!!tabs&&tabs.getBoundingClientRect().top<98&&window.scrollY>0;state.sticky=should;stack.classList.toggle('shown',should);const navHome=document.querySelector('.bottom-nav button[data-go="nav:home"]');if(navHome){const html=icon(should?'rocket':'home',24);navHome.querySelector('.nav-icon').innerHTML=html;navHome.lastElementChild.textContent=should?'Top':'Gogo';navHome.setAttribute('aria-label',should?'Back to top':'Gogo')}syncCategoryFromScroll()}
function handle(action){if(accountAction(action))return;if(action==='login-close'){closeLogin();return}if(action==='home-back'||action==='content-back'){homeBack();return}if(action==='home'||action==='nav:home'){homeReset();return}if(action.startsWith('nav:')){const p=action.split(':')[1];if(p==='promo'||p==='cricket')setPage(p);else{state.modal=p==='earn'?'Earn':'Get ₹500';render()}return}if(action==='drawer'){state.drawer=true;render();return}if(action==='drawer-close'){state.drawer=false;render();return}if(action==='profile'){state.keepDrawer=state.drawer;setPage('profile');return}if(action==='gifts'){state.keepDrawer=state.drawer;setPage('gifts');return}if(action==='bets'){const target=document.querySelector('.bets-section');if(target){const y=window.scrollY+target.getBoundingClientRect().top-156;window.scrollTo({top:Math.max(0,y),behavior:'instant'});syncSticky()}return}if(action.startsWith('cat:')){openCategory(action.split(':')[1]);return}if(action.startsWith('detail:')){state.detail=action.split(':')[1];state.shuffle=0;setPage('detail');return}if(action==='shuffle'){state.shuffle++;render();return}if(action==='more'){const y=window.scrollY;state.more=!state.more;render();window.scrollTo({top:y,behavior:'instant'});return}if(action.startsWith('promo:')){state.promo=action.split(':')[1];render();return}if(action.startsWith('bet:')){const y=window.scrollY;state.bets=action.split(':')[1];render();window.scrollTo({top:y,behavior:'instant'});return}if(action.startsWith('slide:')){let [,id,d]=action.split(':');const rail=document.getElementById(id+'-rail');if(rail){rail.dataset.manualUntil=Date.now()+5500;rail.scrollBy({left:Number(d)*210,behavior:'smooth'})}return}if(action==='race'||action==='cricket'){setPage(action);return}if(action==='login'){state.loginReturn={page:state.page,scrollY:window.scrollY};state.loginStep=1;verificationDeadlines.login=0;setPage('login');return}if(action==='login-next'){const s=document.getElementById('login-input')?.value.trim()||'';if(s.replace(/\D/g,'').length<7){state.modal='Enter a valid mobile number';render()}else{state.loginStep=2;startVerificationCountdown('login');render()}return}if(action==='login-submit'){const s=document.getElementById('login-input')?.value.trim()||'';if(!/^\d{4,6}$/.test(s)){state.modal='Enter the 4–6 digit demo code';render()}else{state.loggedIn=true;state.loginReturn=null;homeReset()}return}if(action==='login-resend'){startVerificationCountdown('login');showToast('Demo code resent');return}if(action==='logout'){state.loggedIn=false;homeReset();return}if(action.startsWith('edit:')){state.editor=action.split(':')[1];state.editorStep=1;state.editGender=state.profile.gender;if(state.editor==='password')startVerificationCountdown('password');render();return}if(action==='edit-close'){state.editor='';render();return}if(action==='nickname-clear'){const input=document.getElementById('edit-value');if(input){input.value='';input.focus()}return}if(action==='day-toggle'){const menu=document.querySelector('.day-options'),trigger=document.querySelector('.day-trigger');if(menu&&trigger){menu.hidden=!menu.hidden;trigger.setAttribute('aria-expanded',String(!menu.hidden))}return}if(action.startsWith('day-select:')){const value=action.slice(11),input=document.getElementById('edit-day'),trigger=document.querySelector('.day-trigger'),menu=document.querySelector('.day-options');if(input&&trigger&&menu){input.value=value;trigger.firstChild.textContent=String(Number(value));trigger.setAttribute('aria-expanded','false');menu.hidden=true;menu.querySelectorAll('[role="option"]').forEach(option=>option.setAttribute('aria-selected',String(option.dataset.go===action)))}return}if(action.startsWith('avatar:')){state.profile.avatar=Number(action.split(':')[1]);render();return}if(action.startsWith('gender:')){state.editGender=action.split(':')[1];render();return}if(action.startsWith('copy:')){copyProfileValue(action.slice(5));return}
if(action.startsWith('verify-resend:')){const kind=action.slice(14);if(!Object.hasOwn(verificationDeadlines,kind))return;startVerificationCountdown(kind);showToast('Demo code resent');return}
if(action==='edit-next'){
  const v=document.getElementById('edit-value')?.value.trim()||'';
  const valid=state.editor==='password'?/^\d{4,6}$/.test(v):state.editor==='phone'?v.replace(/\D/g,'').length>=7:/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(v);
  if(!valid){state.modal=state.editor==='password'?'Enter a 4–6 digit demo code':state.editor==='phone'?'Enter a valid phone number':'Enter a valid e-mail address';render();return}
  state.editDraft=v;state.editorStep=2;if(state.editor==='phone'||state.editor==='email')startVerificationCountdown(state.editor);render();return
}
if(action==='edit-save'){
  const type=state.editor;
  const v=document.getElementById('edit-value')?.value.trim()||'';
  if(type==='birthday'){
    const day=document.getElementById('edit-day')?.value,month=document.getElementById('edit-month')?.value;
    if(!day||!month){state.modal='Choose a day and month';render();return}
    state.profile.birthday=day+'/'+month;
  }else if(type==='password'){
    const password=document.getElementById('edit-password')?.value||'';
    const confirm=document.getElementById('edit-confirm')?.value||'';
    if(password.length<6||password!==confirm){state.modal=password.length<6?'Use at least 6 characters':'Passwords do not match';render();return}
    state.profile.password=password;
  }else if(type==='phone'||type==='email'){
    if(!/^\d{4,6}$/.test(v)){state.modal='Enter a 4–6 digit demo code';render();return}
    state.profile[type]=state.editDraft;
  }else if(type==='nickname'){
    if(!v){state.modal='Please enter your nickname';render();return}
    state.profile.nickname=v;
  }else if(type==='gender'){
    state.profile.gender=state.editGender||state.profile.gender;
  }else if(type==='bind'){
    if(!v){state.modal='Please complete this field';render();return}
    state.profile.invite=v;
  }
  state.editor='';render();showToast('Updated successfully');return
}
if(action.startsWith('content:')){state.content=action.split(':')[1];state.keepDrawer=state.drawer;setPage('content');return}if(action==='download-close'){state.download=false;render();return}if(action==='modal-close'){state.modal='';render();return}state.modal=action.startsWith('game:')?action.slice(5):action.startsWith('offer:')?action.slice(6):action.startsWith('social:')?`${action.slice(7)} Community`:action.startsWith('match:')?action.slice(6):action.startsWith('modal:')?action.slice(6):action==='support'?'Customer Support':action==='messages'?'Messages':action==='deposit'?'Deposit':action==='withdraw'?'Withdraw':action==='activity'?'VIP Activity':action;render()}
function requiresLogin(action){return action==='drawer'||action==='profile'||action==='messages'||action==='notifications'||action==='transactions'||action==='nav:earn'||action==='nav:get500'||action.startsWith('game:')||(action.startsWith('offer:')&&state.promo==='Agent')}
app.addEventListener('submit',e=>{if(e.target?.id!=='gift-form')return;e.preventDefault();const code=document.getElementById('gift-code')?.value.trim()||'';if(!code){showToast('Please enter a gift code');document.getElementById('gift-code')?.focus();return}showToast('Code submitted for demo')});
app.addEventListener('click',e=>{const btn=e.target.closest('[data-go]');if(!btn)return;if(btn.classList.contains('scrim')&&e.target!==btn)return;e.preventDefault();const action=btn.dataset.go;if(!state.loggedIn&&requiresLogin(action)){handle('login');return}if(action.startsWith('banner:')){selectBanner(Number(action.slice(7)),true);return}if(action==='activity-toggle'){state.activityOpen=!state.activityOpen;render();return}if(action.startsWith('activity:')){state.modal=`${action.slice(9)} Activity`;state.activityOpen=false;render();return}handle(action)});
let bannerTouchStart=null;
app.addEventListener('touchstart',e=>{if(e.target.closest('.banner-carousel'))bannerTouchStart={x:e.changedTouches[0].clientX,y:e.changedTouches[0].clientY}},{passive:true});
app.addEventListener('touchend',e=>{if(!bannerTouchStart||!e.target.closest('.banner-carousel')){bannerTouchStart=null;return}const dx=e.changedTouches[0].clientX-bannerTouchStart.x,dy=e.changedTouches[0].clientY-bannerTouchStart.y;bannerTouchStart=null;if(Math.abs(dx)>35&&Math.abs(dx)>Math.abs(dy)*1.3){selectBanner(state.banner+(dx<0?1:-1),true);e.preventDefault()}},{passive:false});
window.addEventListener('scroll',()=>{if(state.page==='home')syncSticky()},{passive:true});
window.addEventListener('resize',syncActivityPosition,{passive:true});
window.addEventListener('popstate',()=>{state.page='home';state.drawer=false;state.editor='';state.modal='';render();window.scrollTo({top:0,behavior:'instant'})});
const reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)');
const onScreen=element=>{const box=element.getBoundingClientRect();return box.bottom>98&&box.top<window.innerHeight};
function advanceRail(selector,cycleCount){const rail=document.querySelector(selector);if(!rail||state.page!=='home'||document.hidden||reducedMotion.matches||!onScreen(rail)||Date.now()<Number(rail.dataset.manualUntil||0))return;const cards=rail.children;if(cards.length<=cycleCount)return;const cycle=cards[cycleCount].offsetLeft-cards[0].offsetLeft;const step=cards[1].offsetLeft-cards[0].offsetLeft;if(rail.scrollLeft>=cycle-step/2){if(selector==='.live-rail'){const winner=rail.querySelector('.winner');if(winner&&winner.dataset.winKey?.startsWith('b-')){const original=cards[Number(winner.dataset.winId)];winner.classList.remove('winner');original?.classList.add('winner');lastLiveWinner=original?.dataset.winKey||lastLiveWinner}}rail.scrollLeft-=cycle}rail.scrollBy({left:step,behavior:'smooth'})}
let lastLiveWinner='';
function updateLiveWinner(){const rail=document.querySelector('.live-rail');if(!rail||state.page!=='home'||document.hidden||reducedMotion.matches||!onScreen(rail))return;const cards=[...rail.children];const visible=cards.filter(card=>{const r=card.getBoundingClientRect(),v=rail.getBoundingClientRect();return r.left>=v.left&&r.right<=v.right});if(!visible.length)return;const choices=visible.filter(card=>card.dataset.winKey!==lastLiveWinner);const pool=choices.length?choices:visible;const winner=pool[Math.floor(Math.random()*pool.length)];lastLiveWinner=winner.dataset.winKey;cards.forEach(card=>card.classList.remove('winner'));winner.classList.add('winner')}
app.addEventListener('pointerdown',event=>{const rail=event.target.closest('.live-rail,.provider-rail,.payment-rail');if(rail)rail.dataset.manualUntil=Date.now()+5500});
app.addEventListener('wheel',event=>{const rail=event.target.closest('.live-rail,.provider-rail,.payment-rail');if(rail)rail.dataset.manualUntil=Date.now()+5500},{passive:true});
let gameRailDrag=null,gameRailDragged=false;
app.addEventListener('pointerdown',event=>{const rail=event.target.closest('.game-grid-rail');if(!rail||event.pointerType!=='mouse')return;gameRailDrag={rail,x:event.clientX,scrollLeft:rail.scrollLeft};gameRailDragged=false});
app.addEventListener('pointermove',event=>{if(!gameRailDrag)return;const distance=event.clientX-gameRailDrag.x;if(Math.abs(distance)>6)gameRailDragged=true;if(gameRailDragged){gameRailDrag.rail.scrollLeft=gameRailDrag.scrollLeft-distance;event.preventDefault()} });
window.addEventListener('pointerup',()=>{gameRailDrag=null});
app.addEventListener('click',event=>{if(!gameRailDragged||!event.target.closest('.game-grid-rail'))return;event.preventDefault();event.stopImmediatePropagation();gameRailDragged=false},true);
setInterval(()=>advanceRail('.live-rail',12),2300);
setInterval(syncVerificationCountdowns,1000);
setInterval(()=>{const carousel=document.querySelector('.banner-carousel');if(!carousel||state.page!=='home'||document.hidden||reducedMotion.matches||state.drawer||state.editor||state.modal||!onScreen(carousel)||Date.now()<bannerManualUntil)return;selectBanner(state.banner+1)},5000);
setInterval(updateLiveWinner,7500);
setInterval(()=>advanceRail('.provider-rail',PROVIDERS.length),2700);
// Activities menu remains stable until the user toggles it.
setInterval(()=>{document.querySelectorAll('.payment-rail').forEach(rail=>{if(document.hidden||reducedMotion.matches||!onScreen(rail)||Date.now()<Number(rail.dataset.manualUntil||0))return;const cards=rail.children;if(cards.length<10)return;const cycle=cards[5].offsetLeft-cards[0].offsetLeft;const step=cards[1].offsetLeft-cards[0].offsetLeft;if(rail.scrollLeft>=cycle-step/2)rail.scrollLeft-=cycle;rail.scrollBy({left:step,behavior:'smooth'})})},2600);
setInterval(()=>{const data=document.querySelector('.bets-data');if(!data||state.page!=='home'||state.bets!=='Casino'||document.hidden||reducedMotion.matches||!onScreen(data)||data.dataset.updating)return;data.dataset.updating='true';state.betTick=(state.betTick||0)+3;data.insertAdjacentHTML('afterbegin',betRow(state.betTick));data.style.transition='none';data.style.transform='translateY(-32px)';void data.offsetHeight;data.style.transition='transform 400ms ease-out';data.style.transform='translateY(0)';setTimeout(()=>{if(!data.isConnected)return;data.lastElementChild?.remove();data.style.transition='none';data.style.transform='';delete data.dataset.updating},430)},2800);
setInterval(()=>{const data=document.querySelector('.fantasy-data');if(!data||state.page!=='home'||state.bets!=='Cricket'||document.hidden||reducedMotion.matches||!onScreen(data)||data.dataset.updating)return;data.dataset.updating='true';state.cricketBetTick=(state.cricketBetTick||0)+3;data.insertAdjacentHTML('afterbegin',cricketBetRow(state.cricketBetTick));data.style.transition='none';data.style.transform='translateY(-32px)';void data.offsetHeight;data.style.transition='transform 400ms ease-out';data.style.transform='translateY(0)';setTimeout(()=>{if(!data.isConnected)return;data.lastElementChild?.remove();data.style.transition='none';data.style.transform='';delete data.dataset.updating},430)},2800);
function raceBetRow([rank,player,wager,prize]){return `<div class="race-bet-row"><span class="race-player"><span class="race-rank">${esc(rank)}.</span><b>${esc(player)}</b></span><strong>₹ ${wager} <i class="flag-india" aria-label="India"></i></strong><strong>₹ ${prize} <i class="flag-india" aria-label="India"></i></strong></div>`}
function bets(){const raceRows=[['1','User310964eH','6,705,444','750,000'],['2','User762670','5,970,700','360,000'],['3','ASHISH','5,718,026.13','240,000'],['4','Incognito','4,474,500','180,000'],['5','User981099','3,625,489','150,000']];return `<section class="home-block bets-section"><div class="section-head"><h2>Bets</h2><span class="live-mark">LIVE <i></i></span></div><div class="segmented"><button class="${state.bets==='Casino'?'active':''}" data-go="bet:Casino">Casino</button><button class="${state.bets==='Cricket'?'active':''}" data-go="bet:Cricket">Cricket</button><button class="${state.bets==='Race'?'active':''}" data-go="bet:Race">Race</button></div><div class="bets-content-window">${state.bets==='Cricket'?`<div class="fantasy-bets"><div class="fantasy-head"><span>Game</span><span>Player</span><span>Payout</span></div><div class="fantasy-viewport"><div class="fantasy-data">${Array.from({length:8},(_,i)=>cricketBetRow((state.cricketBetTick||0)+i)).join('')}</div></div></div>`:state.bets==='Race'?`<div class="race-preview race-bets-preview"><div class="race-preview-head"><b>Player</b><b>Total Wager</b><b>Estimated Prize</b></div>${raceRows.map((row,i)=>raceBetRow(row,i)).join('')}<button class="outline-cta" data-go="race">View All ${icon('chevron',14)}</button></div>`:`<div class="bets-table"><div class="bets-row table-head"><span>Game</span><span>Player</span><span>Payout</span></div><div class="bets-viewport"><div class="bets-data">${Array.from({length:8},(_,i)=>betRow((state.betTick||0)+i)).join('')}</div></div></div>`}</div></section>`}
render();

